package fjc.output;

import fjc.pipeline.ProjectLayout;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.List;

/**
 * Copies the support files unchanged into the output package. These files are
 * NOT generated by the compiler: app.py is the analysed input, style.css and
 * script.js are static assets referenced by the generated pages.
 */
// نقل ملفات التطبيق والتنسيق والتفاعل المساندة دون إعادة توليد محتوياتها.
public final class FileCopier {

    public List<Path> copySupportFiles(ProjectLayout layout, Path outputDir, GenerationLog log) throws IOException {
        Files.createDirectories(outputDir);
        List<Path> copied = new ArrayList<>();
        Path app = outputDir.resolve(layout.appFile().getFileName().toString());
        // هذا نسخ حرفي لملف التطبيق المساند وليس إعادة توليد لشفرة بايثون.
        Files.copy(layout.appFile(), app, StandardCopyOption.REPLACE_EXISTING);
        copied.add(app);
        log.info("Copied support file (analysed input, not generated): " + layout.appFile().getFileName() + " -> " + GenerationLog.display(app));
        for (Path file : layout.staticFiles()) {
            Path relative = layout.staticDir().relativize(file);
            Path target = outputDir.resolve(relative.toString());
            if (target.getParent() != null) Files.createDirectories(target.getParent());
            // تُنقل ملفات التصميم والتفاعل كما هي، ولا تمر على عارض قوالب جينجا.
            Files.copy(file, target, StandardCopyOption.REPLACE_EXISTING);
            copied.add(target);
            log.info("Copied support file (unchanged): " + relative.toString().replace('\\', '/') + " -> " + GenerationLog.display(target));
        }
        return copied;
    }
}
